<?php
declare(strict_types=1);
require_once __DIR__.'/finance_core.php';require_once __DIR__.'/scheduler.php';require_once __DIR__.'/invoice_archive.php';
function receivableState(PDO $pdo,int $id,bool $lock=false):array {
 $q=$pdo->prepare('SELECT * FROM invoices WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$invoice=$q->fetch();if(!$invoice||$invoice['document_kind']!=='invoice')throw new RuntimeException('Rechnung nicht gefunden.');
 $q=$pdo->prepare('SELECT id,amount_cents,reversal_of FROM finance_payments WHERE invoice_id=? ORDER BY id LIMIT 5001'.($lock?' FOR UPDATE':''));$q->execute([$id]);$payments=$q->fetchAll();if(count($payments)>5000)throw new RuntimeException('Zu viele Zahlungszeilen; fachlich prüfen.');$paid=0;foreach($payments as $p)$paid+=(int)$p['amount_cents'];$gross=financeCents($invoice['gross_total']);
 $q=$pdo->prepare('SELECT id,stage,issued_on,outstanding_cents FROM invoice_reminders WHERE invoice_id=? ORDER BY stage'.($lock?' FOR UPDATE':''));$q->execute([$id]);$reminders=$q->fetchAll();
 return ['invoice'=>$invoice,'payments'=>$payments,'reminders'=>$reminders,'paid_cents'=>$paid,'outstanding_cents'=>$invoice['status']==='paid'?0:max(0,$gross-$paid)];
}
function receivableFingerprint(array $state):string {return hash('sha256',json_encode($state,JSON_THROW_ON_ERROR));}
function reminderInput(array $in,array $state):array {
 $date=(string)($in['issued_on']??'');$due=(string)($in['due_on']??'');$body=trim((string)($in['body']??''));$invoice=$state['invoice'];$today=(new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');
 if(($invoice['currency']??'EUR')!=='EUR'||!zgsValidDate((string)$invoice['invoice_date'])||empty($invoice['number'])||trim($invoice['recipient_name'])===''||trim($invoice['recipient_address'])===''||trim($invoice['issuer_name'])===''||trim($invoice['issuer_address'])==='')throw new RuntimeException('EUR-Rechnung und vollständige ursprüngliche Empfänger-/Ausstellerdaten erforderlich.');
 if(!zgsValidDate($date)||!zgsValidDate($due)||$due<=$date||$date>$today||$date<$invoice['invoice_date'])throw new InvalidArgumentException('Datum prüfen: Erinnerung nicht zukünftig/vor Rechnung; Zahlungsziel nach Erinnerungsdatum.');
 if($invoice['status']!=='issued'||$state['outstanding_cents']<1||!zgsValidDate((string)$invoice['due_date'])||$invoice['due_date']>=$date)throw new RuntimeException('Nur offene, nach Fälligkeit liegende Rechnung erinnern.');
 $stage=count($state['reminders'])+1;if($stage>3)throw new RuntimeException('Drei Erinnerungsstufen vorhanden; weitere Schritte gesondert prüfen.');if($state['reminders']&&$date<=end($state['reminders'])['issued_on'])throw new RuntimeException('Nächste Stufe erst mit späterem Erinnerungsdatum.');
 if($body===''||mb_strlen($body)>5000||!mb_check_encoding($body,'UTF-8')||str_contains($body,"\0"))throw new InvalidArgumentException('Erinnerungstext erforderlich, maximal 5000 Zeichen.');
 return ['stage'=>$stage,'issued_on'=>$date,'due_on'=>$due,'body'=>$body,'outstanding_cents'=>$state['outstanding_cents']];
}
function reminderSavePreview(PDO $pdo,int $admin,int $id,array $in):string {
 if($admin<1)throw new RuntimeException('Anmeldung erforderlich.');$pdo->beginTransaction();try{$state=receivableState($pdo,$id,true);$data=reminderInput($in,$state);$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO invoice_reminder_proposals(token,admin_id,invoice_id,fingerprint,payload) VALUES(?,?,?,?,?)')->execute([$token,$admin,$id,receivableFingerprint($state),json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$pdo->commit();return $token;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function reminderPdf(array $invoice,array $data):string {
 $p=new GszInvoicePdf();$p->documentLabel='ZAHLUNGSERINNERUNG';$p->documentNumber=(string)$invoice['number'].' / Stufe '.$data['stage'];$p->AddPage();foreach(['Von: '.$invoice['issuer_name'],$invoice['issuer_address'],'','An: '.$invoice['recipient_name'],$invoice['recipient_address'],'','Erinnerungsdatum: '.$data['issued_on'],'Rechnung: '.$invoice['number'].' vom '.$invoice['invoice_date'],'Offener Betrag: '.financeDecimal((int)$data['outstanding_cents']).' EUR','Zahlungsziel: '.$data['due_on'],'',$data['body'],'','IBAN: '.$invoice['issuer_iban'],'Keine automatisch berechneten Mahngebühren/Zinsen.'] as $line)$p->paragraph((string)$line);return $p->Output('S');
}
function reminderApply(PDO $pdo,int $admin,string $token):int {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM invoice_reminder_proposals WHERE token=? AND admin_id=? FOR UPDATE');$q->execute([$token,$admin]);$proposal=$q->fetch();if(!$proposal)throw new RuntimeException('Vorschau nicht gefunden.');if($proposal['applied_id']){$pdo->commit();return (int)$proposal['applied_id'];}if(strtotime($proposal['created_at'].' UTC')<time()-7200)throw new RuntimeException('Vorschau abgelaufen. Neu berechnen.');
 $state=receivableState($pdo,(int)$proposal['invoice_id'],true);if(!hash_equals($proposal['fingerprint'],receivableFingerprint($state)))throw new RuntimeException('Rechnung/Zahlungen/Erinnerungen inzwischen geändert. Vorschau neu erstellen.');$data=json_decode($proposal['payload'],true,32,JSON_THROW_ON_ERROR);$checked=reminderInput($data,$state);if($checked!==$data)throw new RuntimeException('Vorschaudaten unplausibel.');$bytes=reminderPdf($state['invoice'],$data);$file=gszStoreBytes('invoices',$bytes);
 $pdo->prepare('INSERT INTO invoice_reminders(invoice_id,stage,issued_on,due_on,outstanding_cents,body,pdf_sha256,pdf_size,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$proposal['invoice_id'],$data['stage'],$data['issued_on'],$data['due_on'],$data['outstanding_cents'],$data['body'],$file['sha256'],$file['size_bytes'],$admin]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE invoice_reminder_proposals SET applied_id=? WHERE token=?')->execute([$id,$token]);invEvent($pdo,(int)$proposal['invoice_id'],'reminder_confirmed','Zahlungserinnerung #'.$id.', kein automatischer Versand');gszAudit($pdo,$admin,'reminder_confirmed',['invoice_id'=>(int)$proposal['invoice_id'],'reminder_id'=>$id,'stage'=>$data['stage']]);$pdo->commit();return $id;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function reminderReadPdf(array $r):string {$bytes=gszReadBytes('invoices',$r['pdf_sha256'],$r['pdf_sha256']);if(strlen($bytes)!==(int)$r['pdf_size']||!str_starts_with($bytes,'%PDF-'))throw new RuntimeException('PDF-Integrität verletzt.');return $bytes;}
